css:
.btn {
  --accent: #6b8eff;
  --boder-radius: 2px;
  --corner-size: 10px;
  --pad: 6px;
  --transition: 0.25s;
  --easing: ease;

  position: relative;
  padding: 0.75rem 2rem;
  cursor: pointer;

  display: inline-flex;
  gap: 0;

  font-family: "Garamond", serif;
  font-style: italic;
  font-size: 1.5rem;
  color: color-mix(in oklab, var(--accent) 50%, #fff 50%);

  background-color: #00000008;
  border: 1px solid color-mix(in oklab, var(--accent) 30%, #fff0 70%);
  border-radius: var(--boder-radius);

  transition:
    text-shadow var(--transition) var(--easing),
    box-shadow var(--transition) var(--easing);
  will-change: text-shadow, box-shadow;
  box-shadow:
    0 0 0 color-mix(in oklab, var(--accent) 20%, #fff 80%),
    0 0 0 color-mix(in oklab, var(--accent) 20%, #fff 80%),
    0 0 0 color-mix(in oklab, var(--accent) 20%, #fff 80%),
    0 0 0 color-mix(in oklab, var(--accent) 20%, #fff9 80%);
}

.btn::after {
  content: "";
  position: absolute;
  pointer-events: none;
  inset: -1px;
  border: 1px solid var(--accent);
  border-radius: inherit;
  mask-image: linear-gradient(
      to right,
      #fff var(--corner-size),
      #fff0 var(--corner-size),
      #fff0 calc(100% - var(--corner-size)),
      #fff calc(100% - var(--corner-size))
    ),
    linear-gradient(
      to bottom,
      #fff var(--corner-size),
      #fff0 var(--corner-size),
      #fff0 calc(100% - var(--corner-size)),
      #fff calc(100% - var(--corner-size))
    );
  mask-composite: intersect;
  transition:
    inset var(--transition) var(--easing),
    border-radius var(--transition) var(--easing);
  will-change: inset;
}

.btn .letter {
  animation: letter-anim 2s ease infinite;
  animation-delay: calc(var(--i) * 0.1s);
  transition: color var(--transition) var(--easing);
}

.btn:hover {
  text-shadow: 0 0 2px white;
  box-shadow:
    0 0 2px 1px color-mix(in oklab, var(--accent) 10%, #fff 90%),
    0 0 4px 1px color-mix(in oklab, var(--accent) 20%, #fff 80%),
    0 0 12px 0px color-mix(in oklab, var(--accent) 40%, #fff 60%),
    0 0 48px 0px color-mix(in oklab, var(--accent) 40%, #fff9 60%);
  &::after {
    inset: calc(-1 * var(--pad) - 2px);
    border-radius: calc(var(--boder-radius) + var(--pad));
  }
  .letter {
    animation: none;
  }
}

.btn:active {
  text-shadow: 0 0 1px white;
  box-shadow:
    0 0 2px 0px color-mix(in oklab, var(--accent) 30%, #fff0 70%),
    0 0 4px 0px color-mix(in oklab, var(--accent) 30%, #fff0 70%),
    0 0 12px 0px color-mix(in oklab, var(--accent) 30%, #fff0 70%),
    0 0 48px 0px color-mix(in oklab, var(--accent) 30%, #fff0 70%);
  &::after {
    inset: -1px;
    border-radius: inherit;
  }
  .letter {
    animation: none;
    color: var(--accent);
  }
}

@keyframes letter-anim {
  50% {
    color: var(--accent);
  }
}
